// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 ts1, uint256 ts2, address actor) public {
        ts1 = bound(ts1, 1, 2 ** 128);
        ts2 = bound(ts2, ts1 + 1, ts1 + 1e18);
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));

        // First valid call: exactly 10 ether, timestamp strictly greater than pastBlockTime (initially 0).
        vm.deal(actor, 20 ether);
        vm.warp(ts1);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // Second valid call: timestamp strictly greater than the first -> must also succeed in P.
        vm.warp(ts2);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // General rule: every sequence of valid (10-ether, strictly increasing timestamp) calls succeeds.
        assertTrue(ok2);
    }
}
